export async function handle(db, request) {
  const key = "seen:" + request.id;
  if (await db.get(key)) {
    return { sent: false };
  }
  await db.append("notifications", {
    eventId: request.id,
    to: request.to,
    body: request.body
  });
  await db.set(key, true);
  return { sent: true };
}

